import{z as l,x as o,o as e,c as s,q as t,j as A,D as E,d as B,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"波动率预测的竞赛与实用","description":"","frontmatter":{"title":"波动率预测的竞赛与实用","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-forecast-competition.md","filePath":"quant/vt-forecast-competition.md","lastUpdated":1791063341000}'),p={name:"quant/vt-forecast-competition.md"};function d(m,a,c,h,u,D){const r=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="波动率预测的竞赛与实用" tabindex="-1">波动率预测的竞赛与实用 <a class="header-anchor" href="#波动率预测的竞赛与实用" aria-label="Permalink to &quot;波动率预测的竞赛与实用&quot;">​</a></h1><div class="epigraph"><p>波动率是金融里最可预测的对象之一，也是最容易被「预测得准」骗着下单的对象之一；竞赛的价值不在名次，而在弄清你赌的是哪一段收益几何。</p><footer>—— 据 Andersen and Bollerslev, 1998；Patton, 2011 整理</footer></div><p><a href="/quant/pf-case-map">上一课</a>把组合构建收在接口纪律上：优化器是误差放大器，约束与税不是实现细节而是策略本身，验收放在成本链与危机故事上，并声明波动率产品的定价与对冲细节是下一门课的对象。深化课问交易台自己的问题：对未来一段时间的波动，你的数字从哪来、信到什么程度、接到哪笔交易上。本课是「波动率交易深化」的第一课，把预测整理成一个可竞赛、可评估、可装配的栈；本课程后续各课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「明天波动多少」有三种答法，信息集与偏差都不同。日收益的平方是噪声极大的测量：一天一个样本，隔夜缺口与微观结构噪声混在里面。日内高频收益加总的已实现波动（RV）把样本提到几百个，但要先做<a href="/quant/noise-variance-estimate">噪声修正</a>与隔夜处理。<a href="/quant/vol-surface">隐含波动率曲面</a>的 IV 是前瞻的，却含风险溢价：市场报价的 IV 系统性高于随后已实现的波动，差值就是<a href="/quant/variance-risk-premium">方差风险溢价</a>。三种测量不统一，任何「模型 A 比 B 准」的结论都先要过测量这一关——这是竞赛第一件要钉死的事。</p><p><span class="marginnote">术语翻译：已实现波动（RV）就是把一天切成成百上千个小段，把每段收益平方加总再开方——用高频数据把「今天到底晃了多大」量出来。它比日收益平方多用几百个样本，噪声自然小得多。</span></p><h3 id="三层模型栈" tabindex="-1">三层模型栈 <a class="header-anchor" href="#三层模型栈" aria-label="Permalink to &quot;三层模型栈&quot;">​</a></h3><ul><li>经典条件方差：<a href="/quant/garch">GARCH</a> 只用日收益，胜在便宜稳健；<a href="/quant/egarch-gjr">EGARCH/GJR</a> 补杠杆效应。</li><li>高频测量驱动：<a href="/quant/har-rv-forecast">HAR</a> 用日、周、月三尺度回归，是 RV 预测的工作马；<a href="/quant/realized-garch">已实现 GARCH</a> 把 RV 测量与收益联立，一步预测明显改进。</li><li>期权横截面：IV 本身是强预测变量，但水平有偏，适合做方向与截距校准，不能直接当预测值。</li></ul><p>竞赛规则同样要钉死：损失用对不完美代理稳健的 <a href="/quant/qlike-vol-forecast-eval">QLIKE</a>，样本外配 Diebold–Mariano 或 SPA 检验；期限对齐；Mincer–Zarnowitz 回归看斜率是否为 1，而不是只看 \\(R^2\\)。</p><p><span class="marginnote">Andersen 与 Bollerslev 在 1998 年回答「怀疑派」：同一批 ARCH 类模型，用日收益平方评估时 \\(R^2\\) 常在 0.1 以下，换成高频 RV 评估后成倍上升——先变的是测量，不是模型。今天任何「新模型吊打基线」的说法，第一步都该检查它换的究竟是测量还是模型。</span></p>',10)),(e(),A(n,null,{default:E(()=>[i(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E6%97%A5%E6%94%B6%E7%9B%8A%E5%B9%B3%E6%96%B9%22%5D%20--%3E%20G%5B%22GARCH%20%E6%97%8F%22%5D%0A%20%20D2%5B%22%E6%97%A5%E5%86%85%E9%AB%98%E9%A2%91%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20K%5B%22%E5%99%AA%E5%A3%B0%E4%BF%AE%E6%AD%A3%20RV%20%2F%20%E6%A0%B8%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20D3%5B%22%E6%9C%9F%E6%9D%83%20IV%22%5D%20--%3E%20A%5B%22IV%20%E6%88%AA%E8%B7%9D%E6%A0%A1%E5%87%86%22%5D%0A%20%20G%20--%3E%20F%5B%22%E5%A4%9A%E6%9C%9F%E6%9D%A1%E4%BB%B6%E6%96%B9%E5%B7%AE%E9%A2%84%E6%B5%8B%22%5D%0A%20%20K%20--%3E%20H%5B%22HAR%20%E4%B8%8E%20Realized%20GARCH%22%5D%0A%20%20H%20--%3E%20F%0A%20%20A%20--%3E%20F%0A%20%20F%20--%3E%20E%5B%22QLIKE%20%E5%8A%A0%E6%A0%B7%E6%9C%AC%E5%A4%96%E6%A3%80%E9%AA%8C%22%5D%0A%20%20E%20--%3E%20U1%5B%22%E4%BB%93%E4%BD%8D%E7%BC%A9%E6%94%BE%22%5D%0A%20%20E%20--%3E%20U2%5B%22rich%20%2F%20cheap%20%E5%88%A4%E6%96%AD%22%5D%0A%20%20E%20--%3E%20U3%5B%22carry%20%E8%AE%B0%E8%B4%A6%E5%9F%BA%E5%87%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预测的用途由收益几何决定，这是「实用」二字的全部内容。同一份条件方差预测，接到不同合同上是三件不同的事：方差互换看已实现方差的水平，预测直接当期望用；<a href="/quant/gamma-scalping-pnl">Gamma scalping</a> 看 \\(\\mathrm{RV}-\\sigma_{\\mathrm{imp}}^2\\) 之差，预测与当前 IV 必须同时进场；<a href="/quant/vol-targeting">波动目标仓位</a>看方差的倒数，预测的低估会被杠杆放大。竞赛里胜出的模型接错几何照样亏钱：HAR 在 QLIKE 上小胜 GARCH，不代表做空方差互换就能赢，因为后者的盈亏由左尾而不是均方误差决定。</p><p>第二个实用原则是条件化重于点预测。波动的水平难测，但「会聚集成簇、会随状态切换」可靠得多：把预测当状态变量去削尾——例如<a href="/quant/momentum-crash">动量崩溃</a>里的市场方差状态——比把预测当点估计去押方向更经得起样本外。</p><p><span class="marginnote">直觉类比：预测波动像预报风力——精确说「下午三点风速 7.2 米每秒」很难，但「要起大风了」可靠得多。把预测当状态变量用（提前收帆、加绳），比把它当精确读数去押注经得起检验。</span></p>',4)),(e(),A(n,null,{default:E(()=>[i(r,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20FC%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E6%9D%A1%E4%BB%B6%E6%96%B9%E5%B7%AE%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20VS%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%3A%E8%B5%8C%20RV%20%E7%9A%84%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20FC%20--%3E%20GS%5B%22Gamma%20scalping%3A%E8%B5%8C%20RV%20%E4%B8%8E%20IV%20%E5%B9%B3%E6%96%B9%E4%B9%8B%E5%B7%AE%22%5D%0A%20%20FC%20--%3E%20VT%5B%22%E6%B3%A2%E5%8A%A8%E7%9B%AE%E6%A0%87%E4%BB%93%E4%BD%8D%3A%E8%B5%8C%201%2F%CF%83%2C%E4%BD%8E%E4%BC%B0%E8%A2%AB%E6%9D%A0%E6%9D%86%E6%94%BE%E5%A4%A7%22%5D%0A%20%20VS%20--%3E%20PATH%5B%22%E7%9B%88%E4%BA%8F%E9%83%BD%E7%94%B1%E5%B7%A6%E5%B0%BE%E4%B8%8E%E7%9B%AF%E5%B8%82%E8%B7%AF%E5%BE%84%E5%86%B3%E5%AE%9A%22%5D%0A%20%20GS%20--%3E%20PATH%0A%20%20VT%20--%3E%20PATH%0A%20%20PATH%20--%3E%20LESSON%5B%22QLIKE%20%E7%AB%9E%E8%B5%9B%E8%B5%A2%E5%AE%B6%E6%8E%A5%E9%94%99%E5%87%A0%E4%BD%95%E7%85%A7%E6%A0%B7%E4%BA%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QLIKE 为什么是默认：Patton 证明当代理变量（你的 RV 估计）不完美时，只有一族损失函数的排序不受代理噪声污染。换 MSE，测量误差的方差直接进损失，模型排序可能被代理噪声翻转——名次测的就是谁的 RV 估计更脏。这也解释了为什么拿 IV 当「真值」评估 RV 模型格外危险：IV 含风险溢价，把它记成预测误差，等于把保险费误记成模型的错。</p><p>IV 的偏差在使用侧反而是信息：条件预测减去条带隐含，就是市场为方差保险付的价格，是后续所有「rich / cheap」判断的锚。所以本课程把预测栈定位成输入层：它不直接产生仓位，只给出后续每课共用的那个数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测收益方向，也不做跳的逐笔分解：跳让 RV 偏大且不可对冲，<a href="/quant/realized-semivariance">已实现半方差</a>与双幂变差是补丁，此处只引用。比较的边界要写明：波动预测的优势常在损失函数的噪声之内，样本外结论必须报置信区间。最后，预测不是仓位——把「预测 RV 高于执行价」直接当卖方信号，忽略左尾与盯市路径，那是下一课开始的全部内容。</p><p><span class="marginnote">常见误区：初学者常拿隐含波动当「真波动」去给已实现模型打分。IV 里掺着保险费，市场长期报得比实际高——把保险费记成模型误差，等于责怪消防队「预报的火总比实际烧的大」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预测竞赛先钉测量：日平方收益、噪声修正 RV、IV 三层信息集，偏差与噪声完全不同。</li><li>模型栈按信息集分工：GARCH 便宜稳健，HAR 与 Realized GARCH 用高频测量，IV 作方向校准。</li><li>评估用 QLIKE 与样本外检验；代理不完美时 MSE 排序可被测量噪声翻转。</li><li>预测的用途由收益几何决定：方差水平、RV 减 IV 平方、倒数缩放是三种合同。</li><li>条件化重于点预测：把波动当状态变量削尾，比押方向经得起样本外。</li><li>出处：Andersen and Bollerslev, 1998；Patton, <em>Journal of Business &amp; Economic Statistics</em>, 2011；测量与模型详见各链接课程。</li></ul>',8))])}const _=l(p,[["render",d]]);export{V as __pageData,_ as default};
